package com.campus.personnel.domain;
import java.time.Instant; import java.util.*;
public record FacultyStaffMember(UUID id,String personnelNumber,String fullName,String email,PersonnelType personnelType,UUID organizationUnitId,PersonnelStatus status,long rowVersion,Instant createdAt,Instant updatedAt){ public FacultyStaffMember{Objects.requireNonNull(id,"id");personnelNumber=required(personnelNumber,32);fullName=required(fullName,160);email=email==null||email.isBlank()?null:email.trim().toLowerCase(Locale.ROOT);if(email!=null&&(email.length()>320||!email.contains("@")))throw new InvalidFacultyStaffMemberException();Objects.requireNonNull(personnelType,"personnelType");Objects.requireNonNull(organizationUnitId,"organizationUnitId");Objects.requireNonNull(status,"status");if(rowVersion<0)throw new InvalidFacultyStaffMemberException();Objects.requireNonNull(createdAt,"createdAt");Objects.requireNonNull(updatedAt,"updatedAt");} public static FacultyStaffMember create(UUID id,String n,String name,String email,PersonnelType type,UUID unit,PersonnelStatus status,Instant now){return new FacultyStaffMember(id,n,name,email,type,unit,status,0,now,now);} private static String required(String value,int max){String result=Objects.requireNonNull(value).trim();int length=result.codePointCount(0,result.length());if(length<2||length>max)throw new InvalidFacultyStaffMemberException();return result;} public static final class InvalidFacultyStaffMemberException extends IllegalArgumentException{} }
